import pytest
from summarize import summarize

def test_basic_aggregation():
    rows = [
        {'region': 'North', 'revenue': 100.50},
        {'region': 'South', 'revenue': 200.00},
        {'region': 'North', 'revenue': 50.25}
    ]
    expected = {'North': 150.75, 'South': 200.00}
    assert summarize(rows) == expected

def test_handling_numeric_strings():
    rows = [
        {'region': 'East', 'revenue': "100"},
        {'region': 'East', 'revenue': "50.5"},
        {'region': 'West', 'revenue': "200"}
    ]
    expected = {'East': 150.5, 'West': 200.0}
    assert summarize(rows) == expected

def test_ignoring_missing_region():
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 50} # Missing region
    ]
    expected = {'North': 100.0}
    assert summarize(rows) == expected

def test_ignoring_non_numeric_revenue():
    rows = [
        {'region': 'South', 'revenue': 200},
        {'region': 'South', 'revenue': 'abc'}, # Unparseable
        {'region': 'South', 'revenue': None} # Missing/None
    ]
    expected = {'South': 200.0}
    assert summarize(rows) == expected

def test_empty_input():
    assert summarize([]) == {}

def test_mixed_valid_and_invalid():
    rows = [
        {'region': 'A', 'revenue': 10},
        {'region': 'B', 'revenue': '20'},
        {'region': 'A', 'revenue': 'invalid'},
        {'region': 'C'}, # Missing revenue
        {'region': 'B', 'revenue': 30.5}
    ]
    expected = {'A': 10.0, 'B': 50.5}
    assert summarize(rows) == expected

